FIELD_VALUE_SEMANTICS = {
    ('apply_revision', 'edits.[].before'): ('text', 'prose', 'Exact consumed source text, without line-number prefixes.'),
    ('apply_revision', 'proposal.edits.[].before'): ('text', 'prose', 'Exact consumed source text, without line-number prefixes.'),
    ('propose_revision', 'edits.[].before'): ('text', 'prose', 'Exact consumed source text, without line-number prefixes.'),
    ('block_change', 'block.before'): ('text', 'prose', 'Exact current addressed source text.'),
    ('block_change', 'clip.before'): ('text', 'prose', 'Exact returned clip source text.'),
    ('block_change', 'destination.before'): ('text', 'prose', 'Exact current destination source text.'),
    ('block_change', 'destination.paragraph.before'): ('text', 'prose', 'Exact current destination paragraph source text.'),
    ('section_change', 'replacement.before'): ('text', 'prose', 'Exact current replacement source text.'),
    ('section_change', 'after_before'): ('text', 'prose', 'Exact current source line at after_line.'),
    ('project_guidance_change', 'before'): ('text', 'guide-document', 'Exact current guide document body.'),
    ('store_artifact', 'before'): ('text', 'artifact', 'Exact prior artifact text, or null for creation.'),
    ('store_artifact', 'expected_revision'): ('digest', 'artifact', 'Exact owner-published artifact revision digest returned by read_artifact.'),
    ('conversation_history', 'before'): ('cursor', '', 'Exact older_cursor returned by conversation history.'),
}


def _annotate_value_semantics(operation, value, path=()):
    if not isinstance(value,dict):return
    for name, child in (value.get('properties') or {}).items():
        address=path+(name,);semantics=FIELD_VALUE_SEMANTICS.get((operation,'.'.join(address)))
        if semantics:
            form,home,description=semantics
            child.update({'x-laplace-value-form':form,'x-laplace-value-home':home,'description':description})
        _annotate_value_semantics(operation,child,address)
    if isinstance(value.get('items'),dict):_annotate_value_semantics(operation,value['items'],path+('[]',))
    for axis in ('oneOf','anyOf','allOf'):
        for child in value.get(axis) or []:_annotate_value_semantics(operation,child,path)


from copy import deepcopy as _schema_copy
for _operation,_schema in list(SCHEMAS.items()):
    SCHEMAS[_operation]=_schema_copy(_schema)
    _annotate_value_semantics(_operation,SCHEMAS[_operation])


def declared_guard_form(operation, field):
    values={form for (owner,path),(form,_home,_meaning) in FIELD_VALUE_SEMANTICS.items()
            if owner==operation and path.split('.')[-1]==field}
    if len(values)>1:raise ValueError('Ambiguous guard carrier requires an exact owner field path')
    return next(iter(values)) if values else None

